def solve(arr):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting O(n log n) with bisect_left to maintain minimal tail values.
    """
    import bisect
    if not arr:
        return 0
    tails = []
    for x in arr:
        # Find position to replace; bisect_left ensures equal values do not increase length
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

