def solve(nums):
    n = len(nums)
    if n <= 1:
        return sorted(nums)
    # find pivot i where nums[i] < nums[i+1] from right
    i = n - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1
    if i == -1:
        return sorted(nums)
    # find rightmost element greater than nums[i]
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # swap
    nums = list(nums)  # copy
    nums[i], nums[j] = nums[j], nums[i]
    # reverse suffix i+1:
    nums[i+1:] = reversed(nums[i+1:])
    return nums

