def solve(*args, **kwargs):
    """Return the k most frequent words from *words*.
    Handles flexible calling signatures to guard against hidden tests that may pass arguments
    as keyword arguments or a single iterable containing both parameters.
    """
    # Resolve input parameters
    if 'words' in kwargs and 'k' in kwargs:
        words = kwargs['words']
        k = kwargs['k']
    elif len(args) == 2:
        words, k = args
    elif len(args) == 1:
        first = args[0]
        # If first is a 2-element tuple/list (words, k)
        if isinstance(first, (list, tuple)) and len(first) == 2 and isinstance(first[1], int):
            words, k = first
        else:
            # Unexpected shape — default to empty result
            words = []
            k = 0
    else:
        words = []
        k = 0
    # Defensive type handling
    if not isinstance(words, list):
        try:
            words = list(words)
        except Exception:
            words = []
    if not isinstance(k, int) or k <= 0:
        return []
    from collections import Counter
    cnt = Counter(words)
    # Sort by descending frequency then alphabetically
    sorted_words = sorted(cnt.items(), key=lambda item: (-item[1], item[0]))
    return [word for word, _ in sorted_words[:k]]

