    elif len(args) == 1:
        # maybe a tuple/list containing both
        first = args[0]
        if isinstance(first, (list, tuple)) and len(first) == 2:
            n, edges = first[0], first[1]
        else:
            # cannot determine, fallback
            n, edges = None, None
    else:
        n = kwargs.get('n')
        edges = kwargs.get('edges')
    if n is None or edges is None:
        # invalid input, return empty
        return []
    # Build adjacency and indegree
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    import heapq
    heap = [i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v]==0:
                heapq.heappush(heap, v)
    if len(order)!=n:
        return []
    return order

