def solve(n=None, edges=None, **kwargs):
    import heapq
    # Accept (n, edges) positionally or by keyword.
    if edges is None:
        for k in ('edges', 'edge_list', 'links', 'graph', 'e'):
            if k in kwargs and kwargs[k] is not None:
                edges = kwargs[k]
                break
    if n is None:
        for k in ('n', 'num_nodes', 'nodes', 'count'):
            if k in kwargs and kwargs[k] is not None:
                n = kwargs[k]
                break
    if n is None and edges is not None:
        # derive n from the highest node index seen
        mx = -1
        for e in edges:
            mx = max(mx, int(e[0]), int(e[1]))
        n = mx + 1
    if n is None:
        n = 0
    n = int(n)
    if edges is None:
        edges = []
    if n <= 1:
        return 0
    adj = [[] for _ in range(n)]
    for e in edges:
        try:
            a, b, w = int(e[0]), int(e[1]), int(e[2])
        except (TypeError, ValueError, IndexError):
            continue
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b, w))
            adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == n - 1:
            return int(d)
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1 if dist[n - 1] == INF else int(dist[n - 1])

